///  One iteration of a decay calibration.
public struct dclIteration: FlatBufferVerifiableTable, FlatbuffersVectorInitializable {

  static func validateVersion() { FlatBuffersVersion_25_12_19() }
  public var __buffer: ByteBuffer! { return _accessor.bb }
  private var _accessor: Table

  public static var id: String { "$DCL" }
  public static func finish(_ fbb: inout FlatBufferBuilder, end: Offset, prefix: Bool = false) { fbb.finish(offset: end, fileId: dclIteration.id, addPrefix: prefix) }
  private init(_ t: Table) { _accessor = t }
  public init(_ bb: ByteBuffer, o: Int32) { _accessor = Table(bb: bb, position: o) }

  private struct VT {
    static let ITERATION: VOffset = 4
    static let CHI_SQUARE: VOffset = 6
    static let OBSERVATIONS: VOffset = 8
    static let MAX_STEP_K: VOffset = 10
    static let MAX_STEP_LN_B: VOffset = 12
    static let MAX_STEP_OFFSET_M: VOffset = 14
  }

  public var ITERATION: UInt32 { let o = _accessor.offset(VT.ITERATION); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  public var CHI_SQUARE: Double { let o = _accessor.offset(VT.CHI_SQUARE); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  public var OBSERVATIONS: UInt32 { let o = _accessor.offset(VT.OBSERVATIONS); return o == 0 ? 0 : _accessor.readBuffer(of: UInt32.self, at: o) }
  ///  Largest step in the correction (K), in any ln B, and in any chain offset
  ///  (m).
  public var MAX_STEP_K: Double { let o = _accessor.offset(VT.MAX_STEP_K); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  public var MAX_STEP_LN_B: Double { let o = _accessor.offset(VT.MAX_STEP_LN_B); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  public var MAX_STEP_OFFSET_M: Double { let o = _accessor.offset(VT.MAX_STEP_OFFSET_M); return o == 0 ? 0.0 : _accessor.readBuffer(of: Double.self, at: o) }
  public static func startdclIteration(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 6) }
  public static func add(ITERATION: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: ITERATION, def: 0, at: VT.ITERATION) }
  public static func add(CHI_SQUARE: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: CHI_SQUARE, def: 0.0, at: VT.CHI_SQUARE) }
  public static func add(OBSERVATIONS: UInt32, _ fbb: inout FlatBufferBuilder) { fbb.add(element: OBSERVATIONS, def: 0, at: VT.OBSERVATIONS) }
  public static func add(MAX_STEP_K: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: MAX_STEP_K, def: 0.0, at: VT.MAX_STEP_K) }
  public static func add(MAX_STEP_LN_B: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: MAX_STEP_LN_B, def: 0.0, at: VT.MAX_STEP_LN_B) }
  public static func add(MAX_STEP_OFFSET_M: Double, _ fbb: inout FlatBufferBuilder) { fbb.add(element: MAX_STEP_OFFSET_M, def: 0.0, at: VT.MAX_STEP_OFFSET_M) }
  public static func enddclIteration(_ fbb: inout FlatBufferBuilder, start: UOffset) -> Offset { let end = Offset(offset: fbb.endTable(at: start)); return end }
  public static func createdclIteration(
    _ fbb: inout FlatBufferBuilder,
    ITERATION: UInt32 = 0,
    CHI_SQUARE: Double = 0.0,
    OBSERVATIONS: UInt32 = 0,
    MAX_STEP_K: Double = 0.0,
    MAX_STEP_LN_B: Double = 0.0,
    MAX_STEP_OFFSET_M: Double = 0.0
  ) -> Offset {
    let __start = dclIteration.startdclIteration(&fbb)
    dclIteration.add(ITERATION: ITERATION, &fbb)
    dclIteration.add(CHI_SQUARE: CHI_SQUARE, &fbb)
    dclIteration.add(OBSERVATIONS: OBSERVATIONS, &fbb)
    dclIteration.add(MAX_STEP_K: MAX_STEP_K, &fbb)
    dclIteration.add(MAX_STEP_LN_B: MAX_STEP_LN_B, &fbb)
    dclIteration.add(MAX_STEP_OFFSET_M: MAX_STEP_OFFSET_M, &fbb)
    return dclIteration.enddclIteration(&fbb, start: __start)
  }

  public static func verify<T>(_ verifier: inout Verifier, at position: Int, of type: T.Type) throws where T: Verifiable {
    var _v = try verifier.visitTable(at: position)
    try _v.visit(field: VT.ITERATION, fieldName: "ITERATION", required: false, type: UInt32.self)
    try _v.visit(field: VT.CHI_SQUARE, fieldName: "CHI_SQUARE", required: false, type: Double.self)
    try _v.visit(field: VT.OBSERVATIONS, fieldName: "OBSERVATIONS", required: false, type: UInt32.self)
    try _v.visit(field: VT.MAX_STEP_K, fieldName: "MAX_STEP_K", required: false, type: Double.self)
    try _v.visit(field: VT.MAX_STEP_LN_B, fieldName: "MAX_STEP_LN_B", required: false, type: Double.self)
    try _v.visit(field: VT.MAX_STEP_OFFSET_M, fieldName: "MAX_STEP_OFFSET_M", required: false, type: Double.self)
    _v.finish()
  }
}

